package dev.po4yka.chur.app.vault

import dev.po4yka.chur.ffi.withChurBuffer
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/** Real Core Graphics parsing and rasterization of two-page and password PDFs. */
class PdfDocumentIosTest {
    @Test
    fun pages_render_with_bounded_pixels_and_explicit_disposal() {
        val first = assertNotNull(render(PLAIN, 1))
        try {
            assertEquals(2, first.pages)
            assertEquals(2048, first.image.width)
            assertEquals(1024, first.image.height)
            val pixel = IntArray(1).also { first.image.readPixels(it, 100, 100, 1, 1) }[0]
            assertTrue(((pixel ushr 16) and 255) > 200)
            assertTrue((pixel and 255) < 30)
        } finally { first.close(); first.close() }
        val second = assertNotNull(render(PLAIN, 2))
        try {
            assertEquals(1024, second.image.width)
            assertEquals(2048, second.image.height)
            val pixel = IntArray(1).also { second.image.readPixels(it, 100, 100, 1, 1) }[0]
            assertTrue((pixel and 255) > 200)
        } finally { second.close() }
    }

    @Test
    fun protected_corrupt_missing_pages_and_oversized_inputs_are_not_previewed() {
        assertNull(render(LOCKED, 1))
        assertNull(render("not a PDF".encodeToByteArray(), 1))
        assertNull(render(PLAIN, 0))
        assertNull(render(PLAIN, 3))
        withChurBuffer(DOCUMENT_PDF_PREVIEW_MAX_BYTES.toInt() + 1) { buffer ->
            assertNull(renderPdfPage(buffer, 1))
        }
    }

    @Test
    fun square_pages_also_fit_the_decimal_four_million_pixel_limit() {
        val square = assertNotNull(pdfRasterSize(10_000.0, 10_000.0))
        assertEquals(2000 to 2000, square)
        listOf(1.0 to 10_000.0, 10_000.0 to 1.0, 4000.0 to 2000.0).forEach { (w, h) ->
            val (width, height) = assertNotNull(pdfRasterSize(w, h))
            assertTrue(width <= 2048 && height <= 2048)
            assertTrue(width.toLong() * height <= 4_000_000L)
        }
        assertNull(pdfRasterSize(Double.POSITIVE_INFINITY, 100.0))
        assertNull(pdfRasterSize(0.0, 100.0))
    }

    private fun render(bytes: ByteArray, page: Int) = withChurBuffer(bytes.size) { buffer ->
        buffer.copyIn(bytes)
        renderPdfPage(buffer, page)
    }

    private companion object {
        // Two page vector PDF. The encrypted variant uses fixture password test.
        val PLAIN = hex("")
        val LOCKED = hex("")
        fun hex(value: String): ByteArray = value.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    }
}
